public sealed class Progress {
    public int Percent { get; private set; }
    public Progress(int percent) => Set(percent);
    public void Set(int value) { if (value is < 0 or > 100) throw new ArgumentOutOfRangeException(nameof(value)); Percent=value; }
}
Console.WriteLine(new Progress(75).Percent);

